import{Un as ul,jn as qw,r as Ai,tn as hg,ur as yT}from"./chunk-CbdW2v9C.js";import"./chunk-Do2WuadP.js";import"./main-7CVFOYPV.js";import{a as k,i as j,n as T,r as _}from"./chunk-4YuWYliI.js";import{t as xe}from"./chunk-DlDZIFde.js";var c=class o{static ɵfac=function(a){return new(a||o)};static ɵcmp=yT({type:o,selectors:[[`nixie-watch-page`]],decls:35,vars:0,consts:[[1,`divider`],[`href`,`https://www.industrialalchemy.org/articleview.php?item=696`,`target`,`_blank`],[`loading`,`lazy`,`imgurId`,`Pj0JfXg`,`aspectRatio`,`971 / 1024`],[`loading`,`lazy`,`imgurId`,`4CJOzEQ`],[`loading`,`lazy`,`imgurId`,`EFVuTdm`,`aspectRatio`,`1436 / 1067`],[`loading`,`lazy`,`imgurId`,`Zb4Fl8T`],[`loading`,`lazy`,`imgurId`,`4Mcgkhp`,`aspectRatio`,`908 / 1024`],[`loading`,`lazy`,`imgurId`,`wMgVzgf`],[`loading`,`lazy`,`imgurId`,`4KsMWDh`],[`loading`,`lazy`,`imgurId`,`dHJe2YO`]],template:function(a,p){a&1&&(Ai(0,`mat-card`)(1,`mat-card-header`)(2,`h1`),qw(3,`Nixie Tube Watch`),ul()(),hg(4,`div`,0),Ai(5,`mat-card-content`)(6,`p`),qw(7,` Around 2017 a friend of mine that is a hardware engineer created a small wristwatch out of `),Ai(8,`a`,1),qw(9,`7 segment minitron displays`),ul(),qw(10,`, and I thought it was incredibly cool. What makes them novel is that they are made from incredibly thin tungsten wires inside a tiny vacuum chamber, emitting light by being heated to between 3,100 to 5,400 degrees Fahrenheit. `),ul(),Ai(11,`p`),qw(12,` Despite never having done hardware engineering beyond Arduino and other simple microcontroller project up till this point, I decided to try something similar, but with nixie tubes. Unlike minitron filament displays, nixie tubes are filled with neon gas and function identical to a neon display, but shrunk down to a much smaller scale. There were many challenges and new things I learned along the way; this was my first time ever using any CAD software for routing PCBs. `),ul(),hg(13,`img`,2),Ai(14,`p`),qw(15,` This design was heavily based on the high voltage power supply circuit created by David Forbes, with many smaller changes to work with a microcontroller of my choice. In the next photo you can see the blank back of the final PCB board design. `),ul(),hg(16,`img`,3),Ai(17,`p`),qw(18,` Here I am trying on the bare PCB after installing some custom lugs out of scrap metal and some cannibalized pogo pins to hold the strap's lugs in place. `),ul(),hg(19,`img`,4),Ai(20,`p`),qw(21,` This was my flashing setup. The In-Circuit Serial programmer output has jumper wires plugged into it, and the jumper wires jump to a ribbon cable (left) where each wire of the ribbon cable is soldered to an exposed section of pcb trace that deals with the ISCP functionality. `),ul(),hg(22,`img`,5),Ai(23,`p`),qw(24,` The back of the watch with programming lines still soldered on. I 3d printed a caseback to shield the components from my skin/sweat. If they directly touched my skin, it would be high enough voltage to shock me. `),ul(),hg(25,`img`,6),Ai(26,`p`),qw(27,` Here's the first test flashing of the MCU with some test code, I added power to it, and it worked first try! `),ul(),hg(28,`img`,7),Ai(29,`p`),qw(30,` Here's how the finished result looks on the wrist `),ul(),hg(31,`img`,8),Ai(32,`p`),qw(33,` And this is the final result! `),ul(),hg(34,`img`,9),ul()())},dependencies:[xe,j,_,k,T],styles:[`[_nghost-%COMP%]{display:block;margin:auto;padding-bottom:1px;width:fit-content}mat-card[_ngcontent-%COMP%]{margin:20px 5%;max-width:1400px}mat-card-title[_ngcontent-%COMP%]{margin-top:20px!important}h1[_ngcontent-%COMP%]{margin-top:0}img[_ngcontent-%COMP%]{width:100%}.divider[_ngcontent-%COMP%]{border-top:1px solid white;margin-bottom:1em}`]})};export{c as NixieWatchPage};